// The pure-Dart inflate on fixed vectors (made with Python's zlib), so it is
// checked on the web too, where shifts and ints behave differently.
import 'dart:convert';
import 'dart:typed_data';

import 'package:dartdicom/src/read/inflate.dart';
import 'package:test/test.dart';

Uint8List _hex(String s) => Uint8List.fromList([
      for (var i = 0; i < s.length; i += 2)
        int.parse(s.substring(i, i + 2), radix: 16),
    ]);

void main() {
  final expected = Uint8List.fromList([
    ...ascii.encode('DICOM deflate vector: '),
    for (var i = 0; i < 256; i++) i,
    for (var i = 0; i < 40; i++) ...ascii.encode('abcabcabcabc'),
  ]);

  test('a stored block', () {
    expect(const PureDartInflate().inflate(_hex(_stored)), expected);
  });

  test('Huffman blocks', () {
    expect(const PureDartInflate().inflate(_hex(_compressed)), expected);
  });
}

const _stored =
    '';

const _compressed =
    '';
